`timescale 1ns/1ps
module m8_softmax_tb;parameter CASE_ID=1;parameter DATA_DIR="data";localparam R=32,K=128,N=4096;
 reg clk=0,rst_n=0,clear=0,iv=0,ordy=0;wire ir,ov,ol,err;wire[15:0]op;wire[6:0]oi;wire[31:0]ic,oc,rc;reg[15:0]s16[0:N-1],e16[0:N-1],e32[0:N-1];reg[31:0]s32[0:N-1];reg mask[0:N-1];integer cy=0,send=0,recv=0,mis=0,last=0,maxrow=0,c,diff,errsum=0,maxerr=0;
 generate if(CASE_ID==1)m8_fp16_softmax d(.clk(clk),.rst_n(rst_n),.clear(clear),.in_valid(iv),.in_ready(ir),.in_first_key(send%K==0),.in_last_key(send%K==K-1),.in_mask(mask[send]),.in_score(s16[send]),.out_valid(ov),.out_ready(ordy),.out_prob_u16(op),.out_key_index(oi),.out_last_key(ol),.input_score_count(ic),.output_prob_count(oc),.row_count(rc),.error(err));else m8_fp32_softmax d(.clk(clk),.rst_n(rst_n),.clear(clear),.in_valid(iv),.in_ready(ir),.in_first_key(send%K==0),.in_last_key(send%K==K-1),.in_mask(mask[send]),.in_score(s32[send]),.out_valid(ov),.out_ready(ordy),.out_prob_u16(op),.out_key_index(oi),.out_last_key(ol),.input_score_count(ic),.output_prob_count(oc),.row_count(rc),.error(err));endgenerate
 always#3.3335 clk=~clk;initial begin $readmemh({DATA_DIR,"/score_fp16.mem"},s16);$readmemh({DATA_DIR,"/score_fp32.mem"},s32);$readmemh({DATA_DIR,"/expected_fp16.mem"},e16);$readmemh({DATA_DIR,"/expected_fp32.mem"},e32);$readmemh({DATA_DIR,"/mask.mem"},mask);repeat(8)@(posedge clk);rst_n<=1;end
 always@(negedge clk)if(rst_n)begin iv<=send<N;ordy<=!((cy%37)>=27&&(cy%37)<=31);end
 always@(posedge clk)if(rst_n)begin cy<=cy+1;if(iv&&ir)send<=send+1;if(err)begin $display("FAIL: M8 error");$finish;end;if(ov&&ordy)begin diff=$signed({1'b0,op})-$signed({1'b0,(CASE_ID==1?e16[recv]:e32[recv])});if(diff<0)diff=-diff;errsum=errsum+diff;if(diff>maxerr)maxerr=diff;if(oi!=(recv%K)||ol!==((recv%K)==K-1)||(CASE_ID==2&&diff!=0))begin if(mis<8)$display("MISMATCH %0d exp=%h got=%h",recv,CASE_ID==1?e16[recv]:e32[recv],op);mis<=mis+1;end recv<=recv+1;if(ol)begin c=cy-last;if(c>maxrow)maxrow=c;last=cy;end if(recv==N-1)begin if(mis==0&&ic==N&&oc==N-1&&rc==R-1)begin $display("M8_SOFTMAX_METRIC_JSON: {\"case\":\"%s\",\"rows\":32,\"keys\":4096,\"protocol_mismatches\":0,\"numeric_mae_u16\":%0f,\"numeric_max_u16\":%0d,\"max_row_cycles\":%0d,\"cycles\":%0d}",CASE_ID==1?"fp16":"fp32",(errsum+diff)/4096.0,diff>maxerr?diff:maxerr,c>maxrow?c:maxrow,cy);$display("PASS: M8 matched softmax");end else $display("FAIL: M8 final mis=%0d ic=%0d oc=%0d rc=%0d",mis,ic,oc,rc);$finish;end end if(cy>500000)begin $display("FAIL: M8 timeout send=%0d recv=%0d",send,recv);$finish;end end
endmodule
